def find_topmost_carpet(n, carpets, point):
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Parameters:
    - n (int): The total number of carpets.
    - carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
    - point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
    int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    try:
        x, y = point
        # Iterate from the last carpet to the first to find the topmost covering one
        for idx in range(n - 1, -1, -1):
            try:
                a, b, g, k = carpets[idx]
            except Exception:
                continue  # skip invalid carpet definitions
            if a <= x <= a + g and b <= y <= b + k:
                return idx + 1  # carpets are 1-indexed
    except Exception:
        pass
    return -1

def max_product(num_str: str, N: int, K: int) -> int:
    # Validate inputs
    if N != len(num_str):
        raise ValueError("N does not match length of num_str")
    if K < 0:
        raise ValueError("K must be non-negative")
    if K == 0:
        return int(num_str)
    if K >= N:
        # Cannot split into more parts than digits
        return 0

    # Precompute integer values for all substrings num_str[j:i]
    substr_val = [[0] * (N + 1) for _ in range(N)]
    for j in range(N):
        val = 0
        for i in range(j + 1, N + 1):
            val = val * 10 + (ord(num_str[i - 1]) - 48)
            substr_val[j][i] = val

    # DP table: dp[k][i] = maximum product for first i characters using k multiplications
    dp = [[0] * (N + 1) for _ in range(K + 1)]
    # Base case: no multiplications
    for i in range(1, N + 1):
        dp[0][i] = substr_val[0][i]

    # Fill DP for k from 1 to K
    for k in range(1, K + 1):
        # At least k+1 digits needed to have k multiplications (k+1 parts)
        for i in range(k + 1, N + 1):
            best = 0
            # Try every possible split position j (end of previous part)
            for j in range(k, i):
                prod = dp[k - 1][j] * substr_val[j][i]
                if prod > best:
                    best = prod
            dp[k][i] = best

    return dp[K][N]

def verify_isbn(isbn: str) -> str:
    parts = isbn.split('-')
    if len(parts) != 4:
        raise ValueError("ISBN format must be 'x-xxx-xxxxx-x'")
    raw = ''.join(parts)
    if len(raw) != 10:
        raise ValueError("ISBN must contain exactly 10 characters excluding hyphens")
    try:
        # first nine digits must be numeric
        first_nine = [int(ch) for ch in raw[:9]]
    except ValueError:
        raise ValueError("The first nine characters of the ISBN must be digits")
    last_char = raw[9]
    if last_char in ('X', 'x'):
        last_val = 10
    elif last_char.isdigit():
        last_val = int(last_char)
    else:
        raise ValueError("Invalid checksum character in ISBN")
    # Calculate checksum
    total = sum((i + 1) * first_nine[i] for i in range(9)) + 10 * last_val
    if total % 11 == 0:
        return "Right"
    # Compute the correct check digit
    s = sum((i + 1) * first_nine[i] for i in range(9))
    for d in range(11):
        if (s + 10 * d) % 11 == 0:
            correct_digit = d
            break
    corrected_char = 'X' if correct_digit == 10 else str(correct_digit)
    corrected_isbn = '-'.join(parts[:3] + [corrected_char])
    return corrected_isbn

