def minimum_students_to_leave(heights):
    """
    Calculate the minimal number of students that need to leave so that the remaining
    students can be arranged in a choir formation. A choir formation is a sequence
    that strictly increases to a peak and strictly decreases thereafter.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 2:
        return 0

    # Longest increasing subsequence ending at each position
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i]:
                if lis[j] + 1 > lis[i]:
                    lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each position
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                if lds[j] + 1 > lds[i]:
                    lds[i] = lds[j] + 1

    # Combine to find the longest bitonic subsequence
    max_len = 0
    for i in range(n):
        current = lis[i] + lds[i] - 1
        if current > max_len:
            max_len = current

    return n - max_len

def total_smoked_cigarettes(n, k):
    if k <= 1:
        return n
    total = n
    butts = n
    while butts >= k:
        new = butts // k
        total += new
        butts = new + (butts % k)
    return total
